import { parseColor, type Rgba } from "./color";
import {
  commandPolygon,
  normalizedArcSpan,
  type PathCommand,
  type Point2D,
} from "./path";
import { evictMapToLimit, evictSetToLimit } from "./lru";

export type Matrix2D = {
  a?: number;
  b?: number;
  c?: number;
  d?: number;
  e?: number;
  f?: number;
  m11?: number;
  m12?: number;
  m21?: number;
  m22?: number;
  m41?: number;
  m42?: number;
};

export type ClipRect = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type TextPaint = {
  font: string;
  fillStyle: string;
  strokeStyle: string;
  lineWidth: number;
  textAlign: CanvasTextAlign;
  textBaseline: CanvasTextBaseline;
  letterSpacing: string;
  wordSpacing: string;
};

type TextureRecord = {
  texture: WebGLTexture;
  width: number;
  height: number;
  lastUsed: number;
  deleted: boolean;
};

type DrawCommand = {
  texture: TextureRecord;
  vertices: number[];
  clip: ClipRect | null;
};

type RasterCanvas = OffscreenCanvas | HTMLCanvasElement;
type RasterContext =
  | OffscreenCanvasRenderingContext2D
  | CanvasRenderingContext2D;

const FLOATS_PER_VERTEX = 8;
const IMAGE_CACHE_LIMIT = 256;
const TEXT_CACHE_LIMIT = 512;

const VERTEX_SHADER = `#version 300 es
precision highp float;
layout(location = 0) in vec2 a_position;
layout(location = 1) in vec2 a_uv;
layout(location = 2) in vec4 a_color;
uniform vec2 u_resolution;
out vec2 v_uv;
out vec4 v_color;
void main() {
  vec2 clip = vec2(
    a_position.x / u_resolution.x * 2.0 - 1.0,
    1.0 - a_position.y / u_resolution.y * 2.0
  );
  gl_Position = vec4(clip, 0.0, 1.0);
  v_uv = a_uv;
  v_color = a_color;
}`;

const FRAGMENT_SHADER = `#version 300 es
precision mediump float;
in vec2 v_uv;
in vec4 v_color;
uniform sampler2D u_texture;
out vec4 outColor;
void main() {
  outColor = texture(u_texture, v_uv) * v_color;
}`;

function matrixValues(matrix: Matrix2D): readonly number[] {
  return [
    matrix.a ?? matrix.m11 ?? 1,
    matrix.b ?? matrix.m12 ?? 0,
    matrix.c ?? matrix.m21 ?? 0,
    matrix.d ?? matrix.m22 ?? 1,
    matrix.e ?? matrix.m41 ?? 0,
    matrix.f ?? matrix.m42 ?? 0,
  ];
}

export function transformPoint(point: Point2D, matrix: Matrix2D): Point2D {
  const [a, b, c, d, e, f] = matrixValues(matrix);
  return {
    x: point.x * a! + point.y * c! + e!,
    y: point.x * b! + point.y * d! + f!,
  };
}

function transformedBounds(points: readonly Point2D[]): ClipRect {
  let minX = Number.POSITIVE_INFINITY;
  let minY = Number.POSITIVE_INFINITY;
  let maxX = Number.NEGATIVE_INFINITY;
  let maxY = Number.NEGATIVE_INFINITY;
  for (const point of points) {
    minX = Math.min(minX, point.x);
    minY = Math.min(minY, point.y);
    maxX = Math.max(maxX, point.x);
    maxY = Math.max(maxY, point.y);
  }
  return {
    x: minX,
    y: minY,
    width: Math.max(0, maxX - minX),
    height: Math.max(0, maxY - minY),
  };
}

function sourceWidth(source: any): number {
  return Number(source.naturalWidth ?? source.videoWidth ?? source.width ?? 0);
}

function sourceHeight(source: any): number {
  return Number(source.naturalHeight ?? source.videoHeight ?? source.height ?? 0);
}

function parseFontSize(font: string): number {
  const match = font.match(/(\d+(?:\.\d+)?)px/);
  return match ? Number(match[1]) : 24;
}

function createRasterCanvas(width: number, height: number): RasterCanvas {
  const safeWidth = Math.max(1, width);
  const safeHeight = Math.max(1, height);
  const doc = (
    globalThis as typeof globalThis & {
      document?: { createElement(tag: "canvas"): HTMLCanvasElement };
    }
  ).document;
  if (doc) {
    const canvas = doc.createElement("canvas");
    canvas.width = safeWidth;
    canvas.height = safeHeight;
    return canvas;
  }
  return new OffscreenCanvas(safeWidth, safeHeight);
}

export class WebGLTelaRenderer {
  readonly gl: WebGL2RenderingContext;
  private readonly canvas: { width: number; height: number };
  private readonly program: WebGLProgram;
  private readonly vao: WebGLVertexArrayObject;
  private readonly vertexBuffer: WebGLBuffer;
  private readonly resolutionLocation: WebGLUniformLocation;
  private readonly whiteTexture: TextureRecord;
  private readonly commands: DrawCommand[] = [];
  private readonly imageCache = new WeakMap<object, TextureRecord>();
  private readonly imageLru = new Set<TextureRecord>();
  private readonly textCache = new Map<string, TextureRecord>();
  private readonly textSources = new Map<string, RasterCanvas>();
  private readonly metricsCanvas = createRasterCanvas(1, 1);
  private readonly metricsContext: RasterContext;
  private frame = 0;
  private disposed = false;

  constructor(
    gl: WebGL2RenderingContext,
    canvas: { width: number; height: number },
  ) {
    this.gl = gl;
    this.canvas = canvas;
    const metrics = this.metricsCanvas.getContext("2d");
    if (!metrics) throw new Error("WebGL text rasterizer requires OffscreenCanvas 2D");
    this.metricsContext = metrics;

    this.program = this.createProgram(VERTEX_SHADER, FRAGMENT_SHADER);
    const vao = gl.createVertexArray();
    const vertexBuffer = gl.createBuffer();
    const resolutionLocation = gl.getUniformLocation(this.program, "u_resolution");
    if (!vao || !vertexBuffer || !resolutionLocation) {
      throw new Error("Unable to allocate WebGL2 renderer resources");
    }
    this.vao = vao;
    this.vertexBuffer = vertexBuffer;
    this.resolutionLocation = resolutionLocation;

    gl.bindVertexArray(vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
    const stride = FLOATS_PER_VERTEX * Float32Array.BYTES_PER_ELEMENT;
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, stride, 0);
    gl.enableVertexAttribArray(1);
    gl.vertexAttribPointer(
      1,
      2,
      gl.FLOAT,
      false,
      stride,
      2 * Float32Array.BYTES_PER_ELEMENT,
    );
    gl.enableVertexAttribArray(2);
    gl.vertexAttribPointer(
      2,
      4,
      gl.FLOAT,
      false,
      stride,
      4 * Float32Array.BYTES_PER_ELEMENT,
    );

    const white = gl.createTexture();
    if (!white) throw new Error("Unable to allocate WebGL2 white texture");
    gl.bindTexture(gl.TEXTURE_2D, white);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      1,
      1,
      0,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      new Uint8Array([255, 255, 255, 255]),
    );
    this.whiteTexture = {
      texture: white,
      width: 1,
      height: 1,
      lastUsed: 0,
      deleted: false,
    };

    gl.useProgram(this.program);
    gl.uniform1i(gl.getUniformLocation(this.program, "u_texture"), 0);
    gl.disable(gl.DEPTH_TEST);
    gl.enable(gl.BLEND);
    gl.blendEquation(gl.FUNC_ADD);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  }

  beginFrame(): void {
    this.commands.length = 0;
    this.frame++;
    const { gl } = this;
    gl.viewport(0, 0, this.canvas.width, this.canvas.height);
    gl.disable(gl.SCISSOR_TEST);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
  }

  queuePathFill(
    commands: readonly PathCommand[],
    matrix: Matrix2D,
    colorValue: unknown,
    alpha: number,
    clip: ClipRect | null,
  ): void {
    const color = this.colorWithAlpha(parseColor(colorValue), alpha);
    if (color[3] <= 0) return;
    for (const command of commands) {
      const polygon = commandPolygon(command).map((point) =>
        transformPoint(point, matrix),
      );
      if (polygon.length < 3) continue;
      const vertices: number[] = [];
      for (let i = 1; i < polygon.length - 1; i++) {
        this.pushTriangle(
          vertices,
          polygon[0]!,
          polygon[i]!,
          polygon[i + 1]!,
          color,
        );
      }
      this.commands.push({
        texture: this.whiteTexture,
        vertices,
        clip,
      });
    }
  }

  queuePathStroke(
    commands: readonly PathCommand[],
    matrix: Matrix2D,
    colorValue: unknown,
    alpha: number,
    lineWidth: number,
    clip: ClipRect | null,
    lineDash: readonly number[] = [],
    lineDashOffset = 0,
  ): void {
    const color = this.colorWithAlpha(parseColor(colorValue), alpha);
    if (color[3] <= 0 || lineWidth <= 0) return;
    for (const command of commands) {
      const local = commandPolygon(command);
      const points = local.map((point) => transformPoint(point, matrix));
      if (points.length < 2) continue;
      const closed =
        command.kind === "polygon"
          ? command.closed
          : command.kind === "arc"
            ? normalizedArcSpan(
                command.startAngle,
                command.endAngle,
                command.counterclockwise,
              ) >=
              Math.PI * 2 - 1e-5
            : true;
      const vertices: number[] = [];
      const edgeCount = closed ? points.length : points.length - 1;
      for (let i = 0; i < edgeCount; i++) {
        const p0 = points[i]!;
        const p1 = points[(i + 1) % points.length]!;
        const dx = p1.x - p0.x;
        const dy = p1.y - p0.y;
        const length = Math.hypot(dx, dy);
        if (length <= 1e-6) continue;
        const nx = (-dy / length) * (lineWidth / 2);
        const ny = (dx / length) * (lineWidth / 2);
        const pattern = lineDash.filter((dash) => dash > 0);
        const drawSegment = (start: number, end: number) => {
          const t0 = start / length;
          const t1 = end / length;
          const s = { x: p0.x + dx * t0, y: p0.y + dy * t0 };
          const e = { x: p0.x + dx * t1, y: p0.y + dy * t1 };
          this.pushQuad(
            vertices,
            { x: s.x + nx, y: s.y + ny },
            { x: e.x + nx, y: e.y + ny },
            { x: e.x - nx, y: e.y - ny },
            { x: s.x - nx, y: s.y - ny },
            color,
            0,
            0,
            1,
            1,
          );
        };
        if (pattern.length === 0) {
          drawSegment(0, length);
        } else {
          const cycle = pattern.reduce((sum, dash) => sum + dash, 0);
          let cursor =
            -(((lineDashOffset % cycle) + cycle) % cycle);
          let patternIndex = 0;
          while (cursor < length) {
            const dashLength = pattern[patternIndex % pattern.length]!;
            if (patternIndex % 2 === 0) {
              const start = Math.max(0, cursor);
              const end = Math.min(length, cursor + dashLength);
              if (end > start) drawSegment(start, end);
            }
            cursor += dashLength;
            patternIndex++;
          }
        }
      }
      this.commands.push({
        texture: this.whiteTexture,
        vertices,
        clip,
      });
    }
  }

  queueImage(
    source: object,
    sourceRect: ClipRect,
    destination: ClipRect,
    matrix: Matrix2D,
    alpha: number,
    smoothing: boolean,
    clip: ClipRect | null,
  ): void {
    const texture = this.textureForImage(source, smoothing);
    if (!texture || destination.width <= 0 || destination.height <= 0) return;
    const p0 = transformPoint(
      { x: destination.x, y: destination.y },
      matrix,
    );
    const p1 = transformPoint(
      { x: destination.x + destination.width, y: destination.y },
      matrix,
    );
    const p2 = transformPoint(
      {
        x: destination.x + destination.width,
        y: destination.y + destination.height,
      },
      matrix,
    );
    const p3 = transformPoint(
      { x: destination.x, y: destination.y + destination.height },
      matrix,
    );
    const u0 = sourceRect.x / texture.width;
    const v0 = sourceRect.y / texture.height;
    const u1 = (sourceRect.x + sourceRect.width) / texture.width;
    const v1 = (sourceRect.y + sourceRect.height) / texture.height;
    const vertices: number[] = [];
    this.pushQuad(
      vertices,
      p0,
      p1,
      p2,
      p3,
      [1, 1, 1, Math.max(0, Math.min(1, alpha))],
      u0,
      v0,
      u1,
      v1,
    );
    this.commands.push({ texture, vertices, clip });
  }

  measureText(text: string, paint: TextPaint): TextMetrics {
    this.configureTextContext(this.metricsContext, paint);
    return this.metricsContext.measureText(text);
  }

  queueText(
    text: string,
    x: number,
    y: number,
    matrix: Matrix2D,
    alpha: number,
    paint: TextPaint,
    mode: "fill" | "stroke",
    clip: ClipRect | null,
    maxWidth?: number,
  ): void {
    if (!text || alpha <= 0) return;
    const key = [
      mode,
      text,
      paint.font,
      paint.fillStyle,
      paint.strokeStyle,
      paint.lineWidth,
      paint.letterSpacing,
      paint.wordSpacing,
    ].join("\u0001");
    let texture: TextureRecord | null | undefined = this.textCache.get(key);
    if (!texture || texture.deleted) {
      const source = this.rasterizeText(text, paint, mode);
      texture = this.createTexture(source, true);
      if (!texture) return;
      this.textCache.set(key, texture);
      this.textSources.set(key, source);
      this.evictTextTextures();
    } else {
      texture.lastUsed = this.frame;
      this.textCache.delete(key);
      this.textCache.set(key, texture);
    }

    const fontSize = parseFontSize(paint.font);
    const padding = Math.max(2, Math.ceil(paint.lineWidth) + 1);
    const contentWidth = Math.max(0, texture.width - padding * 2);
    const contentHeight = Math.max(1, texture.height - padding * 2);
    let left = x - padding;
    if (paint.textAlign === "center") left -= contentWidth / 2;
    else if (
      paint.textAlign === "right" ||
      paint.textAlign === "end"
    ) {
      left -= contentWidth;
    }
    let top = y - padding;
    if (paint.textBaseline === "middle") top -= fontSize / 2;
    else if (
      paint.textBaseline === "bottom" ||
      paint.textBaseline === "ideographic"
    ) {
      top -= fontSize;
    } else if (paint.textBaseline === "alphabetic") {
      top -= fontSize * 0.8;
    }

    const requestedWidth =
      maxWidth && maxWidth > 0
        ? Math.min(texture.width, maxWidth + padding * 2)
        : texture.width;
    this.queueTextureQuad(
      texture,
      { x: left, y: top, width: requestedWidth, height: contentHeight + padding * 2 },
      matrix,
      alpha,
      clip,
      requestedWidth / texture.width,
    );
  }

  pathBounds(
    command: PathCommand,
    matrix: Matrix2D,
  ): ClipRect {
    return transformedBounds(
      commandPolygon(command).map((point) => transformPoint(point, matrix)),
    );
  }

  flush(): void {
    if (this.disposed || this.commands.length === 0) return;
    const { gl } = this;
    gl.useProgram(this.program);
    gl.bindVertexArray(this.vao);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.vertexBuffer);
    gl.uniform2f(
      this.resolutionLocation,
      this.canvas.width,
      this.canvas.height,
    );
    gl.activeTexture(gl.TEXTURE0);

    let index = 0;
    while (index < this.commands.length) {
      const first = this.commands[index]!;
      const vertices = [...first.vertices];
      let next = index + 1;
      while (
        next < this.commands.length &&
        this.commands[next]!.texture === first.texture &&
        sameClip(this.commands[next]!.clip, first.clip)
      ) {
        vertices.push(...this.commands[next]!.vertices);
        next++;
      }
      this.applyClip(first.clip);
      gl.bindTexture(gl.TEXTURE_2D, first.texture.texture);
      gl.bufferData(
        gl.ARRAY_BUFFER,
        new Float32Array(vertices),
        gl.DYNAMIC_DRAW,
      );
      gl.drawArrays(gl.TRIANGLES, 0, vertices.length / FLOATS_PER_VERTEX);
      index = next;
    }
    gl.disable(gl.SCISSOR_TEST);
    this.commands.length = 0;
    this.evictImageTextures();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    const { gl } = this;
    for (const texture of this.imageLru) this.deleteTexture(texture);
    for (const texture of this.textCache.values()) this.deleteTexture(texture);
    this.deleteTexture(this.whiteTexture);
    gl.deleteBuffer(this.vertexBuffer);
    gl.deleteVertexArray(this.vao);
    gl.deleteProgram(this.program);
    this.imageLru.clear();
    this.textCache.clear();
    this.textSources.clear();
    this.commands.length = 0;
  }

  private queueTextureQuad(
    texture: TextureRecord,
    destination: ClipRect,
    matrix: Matrix2D,
    alpha: number,
    clip: ClipRect | null,
    maxU: number,
  ): void {
    const p0 = transformPoint({ x: destination.x, y: destination.y }, matrix);
    const p1 = transformPoint(
      { x: destination.x + destination.width, y: destination.y },
      matrix,
    );
    const p2 = transformPoint(
      {
        x: destination.x + destination.width,
        y: destination.y + destination.height,
      },
      matrix,
    );
    const p3 = transformPoint(
      { x: destination.x, y: destination.y + destination.height },
      matrix,
    );
    const vertices: number[] = [];
    this.pushQuad(
      vertices,
      p0,
      p1,
      p2,
      p3,
      [1, 1, 1, Math.max(0, Math.min(1, alpha))],
      0,
      0,
      maxU,
      1,
    );
    this.commands.push({ texture, vertices, clip });
  }

  private textureForImage(
    source: object,
    smoothing: boolean,
  ): TextureRecord | null {
    let texture: TextureRecord | null | undefined = this.imageCache.get(source);
    if (!texture || texture.deleted) {
      texture = this.createTexture(source, smoothing);
      if (!texture) return null;
      this.imageCache.set(source, texture);
      this.imageLru.add(texture);
    }
    texture.lastUsed = this.frame;
    this.imageLru.delete(texture);
    this.imageLru.add(texture);
    return texture;
  }

  private createTexture(
    source: object,
    smoothing: boolean,
  ): TextureRecord | null {
    const width = sourceWidth(source);
    const height = sourceHeight(source);
    if (!(width > 0 && height > 0)) return null;
    const { gl } = this;
    const texture = gl.createTexture();
    if (!texture) return null;
    gl.bindTexture(gl.TEXTURE_2D, texture);
    const filter = smoothing ? gl.LINEAR : gl.NEAREST;
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA,
      gl.RGBA,
      gl.UNSIGNED_BYTE,
      source as TexImageSource,
    );
    return {
      texture,
      width,
      height,
      lastUsed: this.frame,
      deleted: false,
    };
  }

  private rasterizeText(
    text: string,
    paint: TextPaint,
    mode: "fill" | "stroke",
  ): RasterCanvas {
    this.configureTextContext(this.metricsContext, paint);
    const metrics = this.metricsContext.measureText(text);
    const fontSize = parseFontSize(paint.font);
    const padding = Math.max(2, Math.ceil(paint.lineWidth) + 1);
    const canvas = createRasterCanvas(
      Math.ceil(metrics.width) + padding * 2,
      Math.ceil(fontSize * 1.25) + padding * 2,
    );
    const context = canvas.getContext("2d");
    if (!context) throw new Error("Unable to create text raster context");
    this.configureTextContext(context, paint);
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.textAlign = "left";
    context.textBaseline = "top";
    if (mode === "fill") {
      context.fillStyle = paint.fillStyle;
      context.fillText(text, padding, padding);
    } else {
      context.strokeStyle = paint.strokeStyle;
      context.lineWidth = paint.lineWidth;
      context.strokeText(text, padding, padding);
    }
    return canvas;
  }

  private configureTextContext(
    context: RasterContext,
    paint: TextPaint,
  ): void {
    context.font = paint.font;
    if ("letterSpacing" in context) context.letterSpacing = paint.letterSpacing;
    if ("wordSpacing" in context) context.wordSpacing = paint.wordSpacing;
  }

  private evictImageTextures(): void {
    evictSetToLimit(this.imageLru, IMAGE_CACHE_LIMIT, (texture) =>
      this.deleteTexture(texture),
    );
  }

  private evictTextTextures(): void {
    evictMapToLimit(this.textCache, TEXT_CACHE_LIMIT, (texture, key) => {
      this.deleteTexture(texture);
      this.textSources.delete(key);
    });
  }

  private deleteTexture(texture: TextureRecord): void {
    if (texture.deleted) return;
    texture.deleted = true;
    this.gl.deleteTexture(texture.texture);
  }

  private colorWithAlpha(color: Rgba, alpha: number): Rgba {
    return [
      color[0],
      color[1],
      color[2],
      color[3] * Math.max(0, Math.min(1, alpha)),
    ];
  }

  private pushTriangle(
    target: number[],
    p0: Point2D,
    p1: Point2D,
    p2: Point2D,
    color: Rgba,
  ): void {
    this.pushVertex(target, p0, 0, 0, color);
    this.pushVertex(target, p1, 1, 0, color);
    this.pushVertex(target, p2, 1, 1, color);
  }

  private pushQuad(
    target: number[],
    p0: Point2D,
    p1: Point2D,
    p2: Point2D,
    p3: Point2D,
    color: Rgba,
    u0: number,
    v0: number,
    u1: number,
    v1: number,
  ): void {
    this.pushVertex(target, p0, u0, v0, color);
    this.pushVertex(target, p1, u1, v0, color);
    this.pushVertex(target, p2, u1, v1, color);
    this.pushVertex(target, p0, u0, v0, color);
    this.pushVertex(target, p2, u1, v1, color);
    this.pushVertex(target, p3, u0, v1, color);
  }

  private pushVertex(
    target: number[],
    point: Point2D,
    u: number,
    v: number,
    color: Rgba,
  ): void {
    target.push(point.x, point.y, u, v, color[0], color[1], color[2], color[3]);
  }

  private applyClip(clip: ClipRect | null): void {
    const { gl } = this;
    if (!clip) {
      gl.disable(gl.SCISSOR_TEST);
      return;
    }
    const x = Math.max(0, Math.floor(clip.x));
    const top = Math.max(0, Math.floor(clip.y));
    const right = Math.min(this.canvas.width, Math.ceil(clip.x + clip.width));
    const bottom = Math.min(
      this.canvas.height,
      Math.ceil(clip.y + clip.height),
    );
    gl.enable(gl.SCISSOR_TEST);
    gl.scissor(
      x,
      Math.max(0, this.canvas.height - bottom),
      Math.max(0, right - x),
      Math.max(0, bottom - top),
    );
  }

  private createProgram(vertexSource: string, fragmentSource: string): WebGLProgram {
    const { gl } = this;
    const compile = (kind: number, source: string): WebGLShader => {
      const shader = gl.createShader(kind);
      if (!shader) throw new Error("Unable to create WebGL2 shader");
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
        const message = gl.getShaderInfoLog(shader) || "unknown shader error";
        gl.deleteShader(shader);
        throw new Error(`WebGL2 shader compilation failed: ${message}`);
      }
      return shader;
    };
    const vertex = compile(gl.VERTEX_SHADER, vertexSource);
    const fragment = compile(gl.FRAGMENT_SHADER, fragmentSource);
    const program = gl.createProgram();
    if (!program) throw new Error("Unable to create WebGL2 program");
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      const message = gl.getProgramInfoLog(program) || "unknown link error";
      gl.deleteProgram(program);
      throw new Error(`WebGL2 program linking failed: ${message}`);
    }
    return program;
  }
}

function sameClip(a: ClipRect | null, b: ClipRect | null): boolean {
  if (a === b) return true;
  return Boolean(
    a &&
      b &&
      a.x === b.x &&
      a.y === b.y &&
      a.width === b.width &&
      a.height === b.height,
  );
}
