import type { render } from "react-tela/render";
import { WebGLTelaContext } from "./context";
import { TelaPath2D } from "./path";
import { WebGLTelaRenderer } from "./renderer";

export type WebGLTelaSurface = {
  readonly canvas: Parameters<typeof render>[1];
  readonly context: WebGLTelaContext;
  readonly renderer: WebGLTelaRenderer;
  attach(root: ReturnType<typeof render>): () => void;
  dispose(): void;
};

export function createWebGLTelaSurface(target: any): WebGLTelaSurface {
  const gl = target.getContext?.("webgl2", {
    alpha: true,
    antialias: false,
    depth: false,
    premultipliedAlpha: false,
  }) as WebGL2RenderingContext | null;
  if (!gl) {
    throw new Error(
      "WebGL2 is required. Build this application with nx.js 1.0.0-beta.6 or newer.",
    );
  }

  const renderer = new WebGLTelaRenderer(gl, target);
  const context = new WebGLTelaContext(renderer, target);
  const canvas = {
    width: target.width,
    height: target.height,
    getContext(type: "2d") {
      return type === "2d" ? context : null;
    },
  } as unknown as Parameters<typeof render>[1];

  return {
    canvas,
    context,
    renderer,
    attach(root) {
      const flush = () => renderer.flush();
      root.addEventListener("render", flush);
      return () => root.removeEventListener("render", flush);
    },
    dispose() {
      renderer.dispose();
    },
  };
}

export { TelaPath2D };
