export type Point2D = { x: number; y: number };

export type PathCommand =
  | { kind: "rect"; x: number; y: number; width: number; height: number }
  | {
      kind: "roundRect";
      x: number;
      y: number;
      width: number;
      height: number;
      radius: number;
    }
  | {
      kind: "arc";
      x: number;
      y: number;
      radius: number;
      startAngle: number;
      endAngle: number;
      counterclockwise: boolean;
    }
  | { kind: "polygon"; points: Point2D[]; closed: boolean };

function radiusValue(
  radii?: number | DOMPointInit | (number | DOMPointInit)[],
): number {
  const value = Array.isArray(radii) ? radii[0] : radii;
  if (typeof value === "number") return Math.max(0, value);
  return Math.max(0, Number(value?.x ?? 0));
}

/**
 * The subset of Path2D used by react-tela. Keeping the commands inspectable
 * lets the WebGL renderer tessellate and hit-test without GPU readback.
 */
export class TelaPath2D {
  readonly commands: PathCommand[] = [];
  private activePolygon: Point2D[] | null = null;

  constructor(_path?: string) {}

  addPath(path: TelaPath2D, transform?: DOMMatrix2DInit): void {
    const a = transform?.a ?? transform?.m11 ?? 1;
    const b = transform?.b ?? transform?.m12 ?? 0;
    const c = transform?.c ?? transform?.m21 ?? 0;
    const d = transform?.d ?? transform?.m22 ?? 1;
    const e = transform?.e ?? transform?.m41 ?? 0;
    const f = transform?.f ?? transform?.m42 ?? 0;
    for (const command of path.commands) {
      if (command.kind === "polygon") {
        this.commands.push({
          ...command,
          points: command.points.map((point) => ({
            x: point.x * a + point.y * c + e,
            y: point.x * b + point.y * d + f,
          })),
        });
      } else {
        // react-tela does not currently call addPath(); retain a useful
        // approximation for translation/uniform scale if that changes.
        const scale = Math.hypot(a, b);
        this.commands.push({
          ...command,
          x: command.x * a + command.y * c + e,
          y: command.x * b + command.y * d + f,
          ...(command.kind === "arc"
            ? { radius: command.radius * scale }
            : {
                width: command.width * scale,
                height: command.height * scale,
                ...(command.kind === "roundRect"
                  ? { radius: command.radius * scale }
                  : {}),
              }),
        } as PathCommand);
      }
    }
  }

  rect(x: number, y: number, width: number, height: number): void {
    this.finishPolygon(false);
    this.commands.push({ kind: "rect", x, y, width, height });
  }

  roundRect(
    x: number,
    y: number,
    width: number,
    height: number,
    radii?: number | DOMPointInit | (number | DOMPointInit)[],
  ): void {
    this.finishPolygon(false);
    this.commands.push({
      kind: "roundRect",
      x,
      y,
      width,
      height,
      radius: Math.min(
        radiusValue(radii),
        Math.abs(width) / 2,
        Math.abs(height) / 2,
      ),
    });
  }

  arc(
    x: number,
    y: number,
    radius: number,
    startAngle: number,
    endAngle: number,
    counterclockwise = false,
  ): void {
    this.finishPolygon(false);
    this.commands.push({
      kind: "arc",
      x,
      y,
      radius,
      startAngle,
      endAngle,
      counterclockwise,
    });
  }

  ellipse(
    x: number,
    y: number,
    radiusX: number,
    radiusY: number,
    rotation: number,
    startAngle: number,
    endAngle: number,
    counterclockwise = false,
  ): void {
    const span = normalizedArcSpan(startAngle, endAngle, counterclockwise);
    const steps = Math.max(12, Math.ceil((span / (Math.PI * 2)) * 48));
    const cosR = Math.cos(rotation);
    const sinR = Math.sin(rotation);
    const points: Point2D[] = [];
    for (let i = 0; i <= steps; i++) {
      const t = startAngle + (counterclockwise ? -1 : 1) * (span * i) / steps;
      const px = Math.cos(t) * radiusX;
      const py = Math.sin(t) * radiusY;
      points.push({
        x: x + px * cosR - py * sinR,
        y: y + px * sinR + py * cosR,
      });
    }
    this.commands.push({ kind: "polygon", points, closed: span >= Math.PI * 2 });
  }

  moveTo(x: number, y: number): void {
    this.finishPolygon(false);
    this.activePolygon = [{ x, y }];
  }

  lineTo(x: number, y: number): void {
    if (!this.activePolygon) this.activePolygon = [{ x, y }];
    else this.activePolygon.push({ x, y });
  }

  closePath(): void {
    this.finishPolygon(true);
  }

  quadraticCurveTo(cpx: number, cpy: number, x: number, y: number): void {
    const start = this.lastPoint();
    const steps = 16;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const mt = 1 - t;
      this.lineTo(
        mt * mt * start.x + 2 * mt * t * cpx + t * t * x,
        mt * mt * start.y + 2 * mt * t * cpy + t * t * y,
      );
    }
  }

  bezierCurveTo(
    cp1x: number,
    cp1y: number,
    cp2x: number,
    cp2y: number,
    x: number,
    y: number,
  ): void {
    const start = this.lastPoint();
    const steps = 20;
    for (let i = 1; i <= steps; i++) {
      const t = i / steps;
      const mt = 1 - t;
      this.lineTo(
        mt ** 3 * start.x +
          3 * mt * mt * t * cp1x +
          3 * mt * t * t * cp2x +
          t ** 3 * x,
        mt ** 3 * start.y +
          3 * mt * mt * t * cp1y +
          3 * mt * t * t * cp2y +
          t ** 3 * y,
      );
    }
  }

  arcTo(x1: number, y1: number, x2: number, y2: number, _radius: number): void {
    this.lineTo(x1, y1);
    this.lineTo(x2, y2);
  }

  snapshot(): PathCommand[] {
    this.finishPolygon(false);
    return this.commands;
  }

  private lastPoint(): Point2D {
    return this.activePolygon?.[this.activePolygon.length - 1] ?? { x: 0, y: 0 };
  }

  private finishPolygon(closed: boolean): void {
    if (this.activePolygon && this.activePolygon.length > 1) {
      this.commands.push({
        kind: "polygon",
        points: this.activePolygon,
        closed,
      });
    }
    this.activePolygon = null;
  }
}

export function normalizedArcSpan(
  start: number,
  end: number,
  counterclockwise: boolean,
): number {
  const tau = Math.PI * 2;
  let span = counterclockwise ? start - end : end - start;
  if (Math.abs(span) >= tau) return tau;
  span %= tau;
  if (span < 0) span += tau;
  return span;
}

export function commandPolygon(command: PathCommand): Point2D[] {
  if (command.kind === "polygon") return command.points;
  if (command.kind === "rect") {
    const { x, y, width, height } = command;
    return [
      { x, y },
      { x: x + width, y },
      { x: x + width, y: y + height },
      { x, y: y + height },
    ];
  }
  if (command.kind === "roundRect") {
    const { x, y, width, height, radius } = command;
    if (radius <= 0) {
      return commandPolygon({ kind: "rect", x, y, width, height });
    }
    const points: Point2D[] = [];
    const corners = [
      [x + width - radius, y + radius, -Math.PI / 2],
      [x + width - radius, y + height - radius, 0],
      [x + radius, y + height - radius, Math.PI / 2],
      [x + radius, y + radius, Math.PI],
    ] as const;
    const segments = 5;
    for (const [cx, cy, start] of corners) {
      for (let i = 0; i <= segments; i++) {
        const angle = start + (Math.PI / 2) * (i / segments);
        points.push({
          x: cx + Math.cos(angle) * radius,
          y: cy + Math.sin(angle) * radius,
        });
      }
    }
    return points;
  }
  const span = normalizedArcSpan(
    command.startAngle,
    command.endAngle,
    command.counterclockwise,
  );
  const steps = Math.max(12, Math.ceil((span / (Math.PI * 2)) * 48));
  const direction = command.counterclockwise ? -1 : 1;
  const points: Point2D[] = [];
  if (span < Math.PI * 2 - 1e-5) points.push({ x: command.x, y: command.y });
  for (let i = 0; i <= steps; i++) {
    const angle =
      command.startAngle + direction * (span * Math.min(i, steps)) / steps;
    points.push({
      x: command.x + Math.cos(angle) * command.radius,
      y: command.y + Math.sin(angle) * command.radius,
    });
  }
  return points;
}
