import {
  commandPolygon,
  normalizedArcSpan,
  TelaPath2D,
  type PathCommand,
  type Point2D,
} from "./path";
import {
  transformPoint,
  type ClipRect,
  type Matrix2D,
  type TextPaint,
  WebGLTelaRenderer,
} from "./renderer";

type Affine = {
  a: number;
  b: number;
  c: number;
  d: number;
  e: number;
  f: number;
};

type ContextState = {
  transform: Affine;
  clip: ClipRect | null;
  globalAlpha: number;
  fillStyle: string | CanvasGradient | CanvasPattern;
  strokeStyle: string | CanvasGradient | CanvasPattern;
  lineWidth: number;
  lineCap: CanvasLineCap;
  lineJoin: CanvasLineJoin;
  lineDash: number[];
  lineDashOffset: number;
  miterLimit: number;
  font: string;
  textAlign: CanvasTextAlign;
  textBaseline: CanvasTextBaseline;
  direction: CanvasDirection;
  letterSpacing: string;
  wordSpacing: string;
  fontKerning: CanvasFontKerning;
  fontStretch: string;
  fontVariantCaps: string;
  imageSmoothingEnabled: boolean;
  imageSmoothingQuality: ImageSmoothingQuality;
  globalCompositeOperation: GlobalCompositeOperation;
  filter: string;
  shadowColor: string;
  shadowBlur: number;
  shadowOffsetX: number;
  shadowOffsetY: number;
};

const IDENTITY: Affine = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };

function initialState(): ContextState {
  return {
    transform: { ...IDENTITY },
    clip: null,
    globalAlpha: 1,
    fillStyle: "#000000",
    strokeStyle: "#000000",
    lineWidth: 1,
    lineCap: "butt",
    lineJoin: "miter",
    lineDash: [],
    lineDashOffset: 0,
    miterLimit: 10,
    font: "10px sans-serif",
    textAlign: "start",
    textBaseline: "alphabetic",
    direction: "inherit",
    letterSpacing: "0px",
    wordSpacing: "0px",
    fontKerning: "auto",
    fontStretch: "normal",
    fontVariantCaps: "normal",
    imageSmoothingEnabled: true,
    imageSmoothingQuality: "low",
    globalCompositeOperation: "source-over",
    filter: "none",
    shadowColor: "rgba(0,0,0,0)",
    shadowBlur: 0,
    shadowOffsetX: 0,
    shadowOffsetY: 0,
  };
}

function affineFrom(matrix?: Matrix2D): Affine {
  if (!matrix) return { ...IDENTITY };
  return {
    a: matrix.a ?? matrix.m11 ?? 1,
    b: matrix.b ?? matrix.m12 ?? 0,
    c: matrix.c ?? matrix.m21 ?? 0,
    d: matrix.d ?? matrix.m22 ?? 1,
    e: matrix.e ?? matrix.m41 ?? 0,
    f: matrix.f ?? matrix.m42 ?? 0,
  };
}

function multiply(left: Affine, right: Affine): Affine {
  return {
    a: left.a * right.a + left.c * right.b,
    b: left.b * right.a + left.d * right.b,
    c: left.a * right.c + left.c * right.d,
    d: left.b * right.c + left.d * right.d,
    e: left.a * right.e + left.c * right.f + left.e,
    f: left.b * right.e + left.d * right.f + left.f,
  };
}

function inversePoint(point: Point2D, matrix: Affine): Point2D {
  const determinant = matrix.a * matrix.d - matrix.b * matrix.c;
  if (Math.abs(determinant) < 1e-9) {
    return { x: Number.POSITIVE_INFINITY, y: Number.POSITIVE_INFINITY };
  }
  const x = point.x - matrix.e;
  const y = point.y - matrix.f;
  return {
    x: (matrix.d * x - matrix.c * y) / determinant,
    y: (-matrix.b * x + matrix.a * y) / determinant,
  };
}

function pointInPolygon(point: Point2D, polygon: readonly Point2D[]): boolean {
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const pi = polygon[i]!;
    const pj = polygon[j]!;
    const intersects =
      pi.y > point.y !== pj.y > point.y &&
      point.x <
        ((pj.x - pi.x) * (point.y - pi.y)) / (pj.y - pi.y || 1e-9) +
          pi.x;
    if (intersects) inside = !inside;
  }
  return inside;
}

function distanceToSegment(point: Point2D, a: Point2D, b: Point2D): number {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const lengthSquared = dx * dx + dy * dy;
  if (lengthSquared <= 1e-9) return Math.hypot(point.x - a.x, point.y - a.y);
  const t = Math.max(
    0,
    Math.min(1, ((point.x - a.x) * dx + (point.y - a.y) * dy) / lengthSquared),
  );
  return Math.hypot(point.x - (a.x + t * dx), point.y - (a.y + t * dy));
}

export function commandContains(command: PathCommand, point: Point2D): boolean {
  if (command.kind === "arc") {
    const distance = Math.hypot(point.x - command.x, point.y - command.y);
    const span = normalizedArcSpan(
      command.startAngle,
      command.endAngle,
      command.counterclockwise,
    );
    if (span >= Math.PI * 2 - 1e-5) return distance <= command.radius;
  }
  return pointInPolygon(point, commandPolygon(command));
}

export function commandStrokes(
  command: PathCommand,
  point: Point2D,
  lineWidth: number,
): boolean {
  const points = commandPolygon(command);
  const closed =
    command.kind === "polygon"
      ? command.closed
      : command.kind === "arc"
        ? normalizedArcSpan(
            command.startAngle,
            command.endAngle,
            command.counterclockwise,
          ) >=
          Math.PI * 2 - 1e-5
        : true;
  const edges = closed ? points.length : Math.max(0, points.length - 1);
  for (let i = 0; i < edges; i++) {
    if (
      distanceToSegment(point, points[i]!, points[(i + 1) % points.length]!) <=
      lineWidth / 2
    ) {
      return true;
    }
  }
  return false;
}

function intersectClip(a: ClipRect | null, b: ClipRect): ClipRect {
  if (!a) return b;
  const x = Math.max(a.x, b.x);
  const y = Math.max(a.y, b.y);
  const right = Math.min(a.x + a.width, b.x + b.width);
  const bottom = Math.min(a.y + a.height, b.y + b.height);
  return {
    x,
    y,
    width: Math.max(0, right - x),
    height: Math.max(0, bottom - y),
  };
}

/**
 * Canvas2D-shaped façade consumed by react-tela. Drawing operations are
 * recorded as GPU commands; only metrics and text rasterization use an
 * offscreen Canvas2D context.
 */
export class WebGLTelaContext {
  readonly canvas: any;
  private state = initialState();
  private readonly stack: ContextState[] = [];
  private currentPath = new TelaPath2D();

  constructor(
    private readonly renderer: WebGLTelaRenderer,
    canvas: any,
  ) {
    this.canvas = canvas;
  }

  get globalAlpha(): number {
    return this.state.globalAlpha;
  }
  set globalAlpha(value: number) {
    this.state.globalAlpha = Math.max(0, Math.min(1, value));
  }
  get fillStyle(): string | CanvasGradient | CanvasPattern {
    return this.state.fillStyle;
  }
  set fillStyle(value: string | CanvasGradient | CanvasPattern) {
    this.state.fillStyle = value;
  }
  get strokeStyle(): string | CanvasGradient | CanvasPattern {
    return this.state.strokeStyle;
  }
  set strokeStyle(value: string | CanvasGradient | CanvasPattern) {
    this.state.strokeStyle = value;
  }
  get lineWidth(): number {
    return this.state.lineWidth;
  }
  set lineWidth(value: number) {
    this.state.lineWidth = value;
  }
  get lineCap(): CanvasLineCap {
    return this.state.lineCap;
  }
  set lineCap(value: CanvasLineCap) {
    this.state.lineCap = value;
  }
  get lineJoin(): CanvasLineJoin {
    return this.state.lineJoin;
  }
  set lineJoin(value: CanvasLineJoin) {
    this.state.lineJoin = value;
  }
  get lineDashOffset(): number {
    return this.state.lineDashOffset;
  }
  set lineDashOffset(value: number) {
    this.state.lineDashOffset = value;
  }
  get miterLimit(): number {
    return this.state.miterLimit;
  }
  set miterLimit(value: number) {
    this.state.miterLimit = value;
  }
  get font(): string {
    return this.state.font;
  }
  set font(value: string) {
    this.state.font = value;
  }
  get textAlign(): CanvasTextAlign {
    return this.state.textAlign;
  }
  set textAlign(value: CanvasTextAlign) {
    this.state.textAlign = value;
  }
  get textBaseline(): CanvasTextBaseline {
    return this.state.textBaseline;
  }
  set textBaseline(value: CanvasTextBaseline) {
    this.state.textBaseline = value;
  }
  get direction(): CanvasDirection {
    return this.state.direction;
  }
  set direction(value: CanvasDirection) {
    this.state.direction = value;
  }
  get letterSpacing(): string {
    return this.state.letterSpacing;
  }
  set letterSpacing(value: string) {
    this.state.letterSpacing = value;
  }
  get wordSpacing(): string {
    return this.state.wordSpacing;
  }
  set wordSpacing(value: string) {
    this.state.wordSpacing = value;
  }
  get fontKerning(): CanvasFontKerning {
    return this.state.fontKerning;
  }
  set fontKerning(value: CanvasFontKerning) {
    this.state.fontKerning = value;
  }
  get fontStretch(): string {
    return this.state.fontStretch;
  }
  set fontStretch(value: string) {
    this.state.fontStretch = value;
  }
  get fontVariantCaps(): string {
    return this.state.fontVariantCaps;
  }
  set fontVariantCaps(value: string) {
    this.state.fontVariantCaps = value;
  }
  get imageSmoothingEnabled(): boolean {
    return this.state.imageSmoothingEnabled;
  }
  set imageSmoothingEnabled(value: boolean) {
    this.state.imageSmoothingEnabled = value;
  }
  get imageSmoothingQuality(): ImageSmoothingQuality {
    return this.state.imageSmoothingQuality;
  }
  set imageSmoothingQuality(value: ImageSmoothingQuality) {
    this.state.imageSmoothingQuality = value;
  }
  get globalCompositeOperation(): GlobalCompositeOperation {
    return this.state.globalCompositeOperation;
  }
  set globalCompositeOperation(value: GlobalCompositeOperation) {
    this.state.globalCompositeOperation = value;
  }
  get filter(): string {
    return this.state.filter;
  }
  set filter(value: string) {
    this.state.filter = value;
  }
  get shadowColor(): string {
    return this.state.shadowColor;
  }
  set shadowColor(value: string) {
    this.state.shadowColor = value;
  }
  get shadowBlur(): number {
    return this.state.shadowBlur;
  }
  set shadowBlur(value: number) {
    this.state.shadowBlur = value;
  }
  get shadowOffsetX(): number {
    return this.state.shadowOffsetX;
  }
  set shadowOffsetX(value: number) {
    this.state.shadowOffsetX = value;
  }
  get shadowOffsetY(): number {
    return this.state.shadowOffsetY;
  }
  set shadowOffsetY(value: number) {
    this.state.shadowOffsetY = value;
  }

  save(): void {
    this.stack.push({
      ...this.state,
      transform: { ...this.state.transform },
      clip: this.state.clip ? { ...this.state.clip } : null,
      lineDash: [...this.state.lineDash],
    });
  }

  restore(): void {
    const previous = this.stack.pop();
    if (previous) this.state = previous;
  }

  resetTransform(): void {
    this.state.transform = { ...IDENTITY };
  }

  setTransform(
    matrixOrA?: Matrix2D | number,
    b?: number,
    c?: number,
    d?: number,
    e?: number,
    f?: number,
  ): void {
    this.state.transform =
      typeof matrixOrA === "number"
        ? {
            a: matrixOrA,
            b: b ?? 0,
            c: c ?? 0,
            d: d ?? 1,
            e: e ?? 0,
            f: f ?? 0,
          }
        : affineFrom(matrixOrA);
  }

  transform(a: number, b: number, c: number, d: number, e: number, f: number): void {
    this.state.transform = multiply(this.state.transform, { a, b, c, d, e, f });
  }

  getTransform(): DOMMatrix {
    return new DOMMatrix([
      this.state.transform.a,
      this.state.transform.b,
      this.state.transform.c,
      this.state.transform.d,
      this.state.transform.e,
      this.state.transform.f,
    ]);
  }

  clearRect(_x: number, _y: number, _width: number, _height: number): void {
    this.renderer.beginFrame();
  }

  fillRect(x: number, y: number, width: number, height: number): void {
    this.renderer.queuePathFill(
      [{ kind: "rect", x, y, width, height }],
      this.state.transform,
      this.state.fillStyle,
      this.state.globalAlpha,
      this.state.clip,
    );
  }

  strokeRect(x: number, y: number, width: number, height: number): void {
    this.renderer.queuePathStroke(
      [{ kind: "rect", x, y, width, height }],
      this.state.transform,
      this.state.strokeStyle,
      this.state.globalAlpha,
      this.state.lineWidth,
      this.state.clip,
      this.state.lineDash,
      this.state.lineDashOffset,
    );
  }

  beginPath(): void {
    this.currentPath = new TelaPath2D();
  }
  rect(x: number, y: number, width: number, height: number): void {
    this.currentPath.rect(x, y, width, height);
  }
  roundRect(
    x: number,
    y: number,
    width: number,
    height: number,
    radii?: number | DOMPointInit | (number | DOMPointInit)[],
  ): void {
    this.currentPath.roundRect(x, y, width, height, radii);
  }
  arc(
    x: number,
    y: number,
    radius: number,
    startAngle: number,
    endAngle: number,
    counterclockwise?: boolean,
  ): void {
    this.currentPath.arc(
      x,
      y,
      radius,
      startAngle,
      endAngle,
      counterclockwise,
    );
  }
  arcTo(x1: number, y1: number, x2: number, y2: number, radius: number): void {
    this.currentPath.arcTo(x1, y1, x2, y2, radius);
  }
  ellipse(
    x: number,
    y: number,
    radiusX: number,
    radiusY: number,
    rotation: number,
    startAngle: number,
    endAngle: number,
    counterclockwise?: boolean,
  ): void {
    this.currentPath.ellipse(
      x,
      y,
      radiusX,
      radiusY,
      rotation,
      startAngle,
      endAngle,
      counterclockwise,
    );
  }
  moveTo(x: number, y: number): void {
    this.currentPath.moveTo(x, y);
  }
  lineTo(x: number, y: number): void {
    this.currentPath.lineTo(x, y);
  }
  closePath(): void {
    this.currentPath.closePath();
  }
  quadraticCurveTo(cpx: number, cpy: number, x: number, y: number): void {
    this.currentPath.quadraticCurveTo(cpx, cpy, x, y);
  }
  bezierCurveTo(
    cp1x: number,
    cp1y: number,
    cp2x: number,
    cp2y: number,
    x: number,
    y: number,
  ): void {
    this.currentPath.bezierCurveTo(cp1x, cp1y, cp2x, cp2y, x, y);
  }

  fill(pathOrRule?: TelaPath2D | CanvasFillRule, _fillRule?: CanvasFillRule): void {
    const path = pathOrRule instanceof TelaPath2D ? pathOrRule : this.currentPath;
    this.renderer.queuePathFill(
      path.snapshot(),
      this.state.transform,
      this.state.fillStyle,
      this.state.globalAlpha,
      this.state.clip,
    );
  }

  stroke(path?: TelaPath2D): void {
    const selectedPath = path ?? this.currentPath;
    this.renderer.queuePathStroke(
      selectedPath.snapshot(),
      this.state.transform,
      this.state.strokeStyle,
      this.state.globalAlpha,
      this.state.lineWidth,
      this.state.clip,
      this.state.lineDash,
      this.state.lineDashOffset,
    );
  }

  clip(pathOrRule?: TelaPath2D | CanvasFillRule, _fillRule?: CanvasFillRule): void {
    const path = pathOrRule instanceof TelaPath2D ? pathOrRule : this.currentPath;
    let bounds: ClipRect | null = null;
    for (const command of path.snapshot()) {
      const commandBounds = this.renderer.pathBounds(
        command,
        this.state.transform,
      );
      if (!bounds) bounds = commandBounds;
      else {
        const x = Math.min(bounds.x, commandBounds.x);
        const y = Math.min(bounds.y, commandBounds.y);
        const right = Math.max(
          bounds.x + bounds.width,
          commandBounds.x + commandBounds.width,
        );
        const bottom = Math.max(
          bounds.y + bounds.height,
          commandBounds.y + commandBounds.height,
        );
        bounds = { x, y, width: right - x, height: bottom - y };
      }
    }
    if (bounds) this.state.clip = intersectClip(this.state.clip, bounds);
  }

  isPointInPath(
    pathOrX: TelaPath2D | number,
    xOrY: number,
    yOrRule?: number | CanvasFillRule,
  ): boolean {
    const path =
      pathOrX instanceof TelaPath2D ? pathOrX : this.currentPath;
    const x = pathOrX instanceof TelaPath2D ? xOrY : pathOrX;
    const y =
      pathOrX instanceof TelaPath2D
        ? Number(yOrRule)
        : xOrY;
    const local = inversePoint({ x, y }, this.state.transform);
    return path.snapshot().some((command) => commandContains(command, local));
  }

  isPointInStroke(
    pathOrX: TelaPath2D | number,
    xOrY: number,
    y?: number,
  ): boolean {
    const path =
      pathOrX instanceof TelaPath2D ? pathOrX : this.currentPath;
    const x = pathOrX instanceof TelaPath2D ? xOrY : pathOrX;
    const pointY = pathOrX instanceof TelaPath2D ? Number(y) : xOrY;
    const local = inversePoint({ x, y: pointY }, this.state.transform);
    return path
      .snapshot()
      .some((command) => commandStrokes(command, local, this.state.lineWidth));
  }

  drawImage(source: any, ...args: number[]): void {
    const width = Number(source.naturalWidth ?? source.width ?? 0);
    const height = Number(source.naturalHeight ?? source.height ?? 0);
    if (!(width > 0 && height > 0)) return;
    let sourceRect: ClipRect;
    let destination: ClipRect;
    if (args.length === 2) {
      sourceRect = { x: 0, y: 0, width, height };
      destination = { x: args[0]!, y: args[1]!, width, height };
    } else if (args.length === 4) {
      sourceRect = { x: 0, y: 0, width, height };
      destination = {
        x: args[0]!,
        y: args[1]!,
        width: args[2]!,
        height: args[3]!,
      };
    } else {
      sourceRect = {
        x: args[0]!,
        y: args[1]!,
        width: args[2]!,
        height: args[3]!,
      };
      destination = {
        x: args[4]!,
        y: args[5]!,
        width: args[6]!,
        height: args[7]!,
      };
    }
    this.renderer.queueImage(
      source,
      sourceRect,
      destination,
      this.state.transform,
      this.state.globalAlpha,
      this.state.imageSmoothingEnabled,
      this.state.clip,
    );
  }

  measureText(text: string): TextMetrics {
    return this.renderer.measureText(text, this.textPaint());
  }

  fillText(text: string, x: number, y: number, maxWidth?: number): void {
    this.renderer.queueText(
      text,
      x,
      y,
      this.state.transform,
      this.state.globalAlpha,
      this.textPaint(),
      "fill",
      this.state.clip,
      maxWidth,
    );
  }

  strokeText(text: string, x: number, y: number, maxWidth?: number): void {
    this.renderer.queueText(
      text,
      x,
      y,
      this.state.transform,
      this.state.globalAlpha,
      this.textPaint(),
      "stroke",
      this.state.clip,
      maxWidth,
    );
  }

  getLineDash(): number[] {
    return [...this.state.lineDash];
  }

  setLineDash(segments: number[]): void {
    this.state.lineDash = [...segments];
  }

  createLinearGradient(): CanvasGradient {
    throw new Error("Canvas gradients are not used by this WebGL UI");
  }
  createRadialGradient(): CanvasGradient {
    throw new Error("Canvas gradients are not used by this WebGL UI");
  }
  createConicGradient(): CanvasGradient {
    throw new Error("Canvas gradients are not used by this WebGL UI");
  }
  createPattern(): CanvasPattern | null {
    return null;
  }

  private textPaint(): TextPaint {
    return {
      font: this.state.font,
      fillStyle:
        typeof this.state.fillStyle === "string"
          ? this.state.fillStyle
          : "#000000",
      strokeStyle:
        typeof this.state.strokeStyle === "string"
          ? this.state.strokeStyle
          : "#000000",
      lineWidth: this.state.lineWidth,
      textAlign: this.state.textAlign,
      textBaseline: this.state.textBaseline,
      letterSpacing: this.state.letterSpacing,
      wordSpacing: this.state.wordSpacing,
    };
  }
}
