export type Rgba = readonly [number, number, number, number];

const NAMED_COLORS: Record<string, Rgba> = {
  black: [0, 0, 0, 1],
  white: [1, 1, 1, 1],
  red: [1, 0, 0, 1],
  green: [0, 0.501960784, 0, 1],
  blue: [0, 0, 1, 1],
  transparent: [0, 0, 0, 0],
  none: [0, 0, 0, 0],
};

function channel(value: string): number {
  if (value.endsWith("%")) return Math.max(0, Math.min(1, Number(value.slice(0, -1)) / 100));
  return Math.max(0, Math.min(1, Number(value) / 255));
}

export function parseColor(input: unknown): Rgba {
  if (typeof input !== "string") return [0, 0, 0, 0];
  const value = input.trim().toLowerCase();
  const named = NAMED_COLORS[value];
  if (named) return named;

  if (value.startsWith("#")) {
    const hex = value.slice(1);
    if (hex.length === 3 || hex.length === 4) {
      return [
        parseInt(hex[0]! + hex[0]!, 16) / 255,
        parseInt(hex[1]! + hex[1]!, 16) / 255,
        parseInt(hex[2]! + hex[2]!, 16) / 255,
        hex.length === 4 ? parseInt(hex[3]! + hex[3]!, 16) / 255 : 1,
      ];
    }
    if (hex.length === 6 || hex.length === 8) {
      return [
        parseInt(hex.slice(0, 2), 16) / 255,
        parseInt(hex.slice(2, 4), 16) / 255,
        parseInt(hex.slice(4, 6), 16) / 255,
        hex.length === 8 ? parseInt(hex.slice(6, 8), 16) / 255 : 1,
      ];
    }
  }

  const rgb = value.match(/^rgba?\((.+)\)$/);
  if (rgb) {
    const values = rgb[1]!.split(/[,\s/]+/).filter(Boolean);
    if (values.length >= 3) {
      return [
        channel(values[0]!),
        channel(values[1]!),
        channel(values[2]!),
        values[3] === undefined
          ? 1
          : Math.max(
              0,
              Math.min(
                1,
                values[3]!.endsWith("%")
                  ? Number(values[3]!.slice(0, -1)) / 100
                  : Number(values[3]),
              ),
            ),
      ];
    }
  }

  return [0, 0, 0, 0];
}
