export function evictMapToLimit<K, V>(
  map: Map<K, V>,
  limit: number,
  onEvict: (value: V, key: K) => void,
): void {
  while (map.size > Math.max(0, limit)) {
    const oldestKey = map.keys().next().value as K | undefined;
    if (oldestKey === undefined) return;
    const value = map.get(oldestKey);
    map.delete(oldestKey);
    if (value !== undefined) onEvict(value, oldestKey);
  }
}

export function evictSetToLimit<T>(
  set: Set<T>,
  limit: number,
  onEvict: (value: T) => void,
): void {
  while (set.size > Math.max(0, limit)) {
    const oldest = set.values().next().value as T | undefined;
    if (oldest === undefined) return;
    set.delete(oldest);
    onEvict(oldest);
  }
}
